INSERT INTO track_feature VALUES ('c23', 0, '🧠', 'Punteros y memoria', 'El concepto que define a C, la gestión manual del heap y las estrategias que escalan.');
INSERT INTO track_feature VALUES ('c23', 1, '✨', 'C23 moderno', 'constexpr, nullptr, typeof, _BitInt, #embed: el C de siempre, más afilado.');
INSERT INTO track_feature VALUES ('c23', 2, '🏗️', 'Build y linking', 'Meson, Make, bibliotecas .a/.so, el linker y el formato ELF por dentro.');
INSERT INTO track_feature VALUES ('c23', 3, '🔗', 'ABI', 'Las convenciones de llamada y la interfaz binaria que une el software compilado.');
INSERT INTO track_feature VALUES ('c23', 4, '📚', 'libc y freestanding', 'glibc vs musl, las syscalls, y el mundo sin libc: bare metal.');
INSERT INTO track_feature VALUES ('c23', 5, '🛡️', 'Sanitizers y fuzzing', 'ASan, UBSan, análisis estático y fuzzing: caza bugs antes de que ocurran.');
INSERT INTO track_feature VALUES ('c23', 6, '⚡', 'Concurrencia y bajo nivel', 'Atomics, el modelo de memoria, SIMD, caché y perf.');
INSERT INTO track_feature VALUES ('c23', 7, '🔱', 'Nivel PhD', 'Tu propia libc, un allocator desde cero, y cómo funciona un compilador.');
INSERT INTO track_feature VALUES ('kernel', 0, '🐧', 'El C del kernel', 'GNU C freestanding, sin libc, con su propio universo de APIs y reglas.');
INSERT INTO track_feature VALUES ('kernel', 1, '🔧', 'Kbuild y módulos', 'Configurar y compilar el kernel, y escribir módulos cargables (LKM).');
INSERT INTO track_feature VALUES ('kernel', 2, '📟', 'Drivers y char devices', 'file_operations, el device model y hablar con el hardware.');
INSERT INTO track_feature VALUES ('kernel', 3, '🔒', 'Concurrencia extrema', 'Spinlocks, mutexes, RCU y las barreras de memoria que escalan a miles de núcleos.');
INSERT INTO track_feature VALUES ('kernel', 4, '🧠', 'Memoria del kernel', 'kmalloc, el slab allocator, páginas y memoria física.');
INSERT INTO track_feature VALUES ('kernel', 5, '⚡', 'Interrupciones', 'IRQ handlers, softirqs, tasklets, workqueues y el planificador.');
INSERT INTO track_feature VALUES ('kernel', 6, '🐞', 'Depuración', 'ftrace, KASAN, lockdep, kgdb: cazar bugs en el corazón del sistema.');
INSERT INTO track_feature VALUES ('kernel', 7, '🦀', 'Rust for Linux', 'El nuevo lenguaje central del kernel: drivers seguros en Rust.');
INSERT INTO track_feature VALUES ('discrete-math', 0, '🧩', 'El lenguaje común', 'Conjuntos, lógica y relaciones: el vocabulario con el que están escritos los papers que quieres leer.');
INSERT INTO track_feature VALUES ('discrete-math', 1, '🪜', 'Inducción e invariantes', 'La demostración que se parece a tu función recursiva, y la que corre dentro de tu bucle.');
INSERT INTO track_feature VALUES ('discrete-math', 2, '🔢', 'Contar sin enumerar', 'Combinatoria, palomar e inclusión-exclusión: por qué las colisiones de hash son inevitables.');
INSERT INTO track_feature VALUES ('discrete-math', 3, '🕸️', 'Grafos de verdad', 'Del DAG de tu build al orden topológico, la conectividad y el coloreado de registros.');
INSERT INTO track_feature VALUES ('discrete-math', 4, '♻️', 'Recurrencias', 'Del teorema maestro al coste real de partir un problema por la mitad.');
INSERT INTO track_feature VALUES ('discrete-math', 5, '🔗', 'Retículos y CRDT', 'Las tres propiedades algebraicas que hacen converger un estado replicado.');
INSERT INTO track_feature VALUES ('neovim', 0,'⌨️', 'La gramática de Vim', 'Operadores + mociones + objetos de texto. Deja de memorizar atajos y empieza a "hablar" el idioma de la edición.');
INSERT INTO track_feature VALUES ('neovim', 1, '🧠', 'LSP nativo 0.12', 'vim.lsp.enable, Mason, diagnósticos y code actions. El motor de un IDE moderno, sin la pesadez.');
INSERT INTO track_feature VALUES ('neovim', 2, '⚡', 'blink.cmp', 'Autocompletado en Rust, fuzzy tolerante a typos y 0.5–4 ms por pulsación.');
INSERT INTO track_feature VALUES ('neovim', 3, '🌳', 'Treesitter', 'Resaltado semántico, objetos de texto inteligentes y selección incremental.');
INSERT INTO track_feature VALUES ('neovim', 4, '🪟', 'tmux + zellij', 'Multiplexores, navegación transparente entre paneles y sesionizadores.');
INSERT INTO track_feature VALUES ('neovim', 5, '🤖', 'IA por capas', 'Copilot/Supermaven, Avante/CodeCompanion y Claude Code integrados en tu flujo.');
INSERT INTO track_feature VALUES ('neovim', 6, '🦀', '4 stacks afinados', 'clangd, rustaceanvim, sourcekit-lsp y el trío React/Tailwind/TS.');
INSERT INTO track_feature VALUES ('neovim', 7, '♻️', 'Automatización total', 'Macros, registros, quickfix, :g y :norm. Tareas repetitivas en una tecla.');
INSERT INTO track_feature VALUES ('rust', 0, '🦀', 'Ownership y borrowing', 'El sistema que garantiza seguridad de memoria sin recolector de basura.');
INSERT INTO track_feature VALUES ('rust', 1, '🧩', 'Traits y genéricos', 'Abstracción sin coste, el sistema de tipos más expresivo de los lenguajes de sistemas.');
INSERT INTO track_feature VALUES ('rust', 2, '⏳', 'Lifetimes', 'Cómo el borrow checker demuestra que tus referencias son válidas.');
INSERT INTO track_feature VALUES ('rust', 3, '⚡', 'Async (edición 2024)', 'async/await, futures, tokio y las async closures del edición 2024.');
INSERT INTO track_feature VALUES ('rust', 4, '🔓', 'Unsafe y FFI', 'Cuando necesitas bajar al metal: unsafe, punteros crudos e interop con C.');
INSERT INTO track_feature VALUES ('rust', 5, '🔩', 'no_std y embebido', 'Rust sin librería estándar: embebido, allocators y el kernel.');
INSERT INTO track_feature VALUES ('rust', 6, '🐞', 'Debugging y profiling', 'Las herramientas para depurar y optimizar Rust en producción.');
INSERT INTO track_feature VALUES ('rust', 7, '🔱', 'Metaprogramación', 'Macros y programación a nivel de tipos: el nivel PhD de Rust.');
INSERT INTO track_feature VALUES ('swift', 0, '🔤', 'Swift 6.3', 'El lenguaje moderno de Apple: opcionales, protocolos, genéricos y typed throws.');
INSERT INTO track_feature VALUES ('swift', 1, '🎨', 'SwiftUI declarativo', 'Construye interfaces con estado reactivo: describe el qué, no el cómo.');
INSERT INTO track_feature VALUES ('swift', 2, '👁️', '@Observable', 'El framework Observation: estado reactivo sin boilerplate, con @State como macro.');
INSERT INTO track_feature VALUES ('swift', 3, '🗄️', 'SwiftData', 'Persistencia con @Model y @Query: sin .xcdatamodeld ni NSManagedObject.');
INSERT INTO track_feature VALUES ('swift', 4, '⚡', 'Concurrencia Swift 6', 'async/await, actores y Sendable con concurrencia estricta que previene data races.');
INSERT INTO track_feature VALUES ('swift', 5, '🌐', 'Redes modernas', 'URLSession con async/await y Codable para consumir APIs sin dolor.');
INSERT INTO track_feature VALUES ('swift', 6, '🧪', 'Swift Testing', 'El nuevo framework de tests con @Test y #expect, más expresivo que XCTest.');
INSERT INTO track_feature VALUES ('swift', 7, '🚀', 'A la App Store', 'Arquitectura, firmas, TestFlight y publicación: de la idea a la tienda.');
