INSERT INTO track VALUES ('arquitectura-cpu', 'La CPU', 'Del fetch al retiro', 'Pipeline, predicción, ejecución fuera de orden y el modelo que el ensamblador te enseña.', 'arquitectura-computadores', 'planned', '#fab387', '#fab387', '#f9e2af', 0, NULL, NULL);
INSERT INTO track VALUES ('jerarquia-memoria', 'Jerarquía de Memoria', 'Cachés, latencias y localidad', 'De los registros al disco: por qué la localidad manda y qué cuesta un fallo de caché.', 'arquitectura-computadores', 'planned', '#fab387', '#fab387', '#f9e2af', 1, NULL, NULL);
INSERT INTO track VALUES ('tcp-ip', 'TCP/IP', 'La pila de protocolos', 'IP, TCP, UDP y DNS: cómo se enruta, se entrega y se pierde un paquete.', 'redes', 'planned', '#89dceb', '#89dceb', '#74c7ec', 0, NULL, NULL);
INSERT INTO track VALUES ('http-web', 'HTTP y la Web', 'El protocolo de la web', 'De HTTP/1.1 a HTTP/3: semántica, caché, TLS y lo que un navegador negocia por ti.', 'redes', 'planned', '#89dceb', '#89dceb', '#74c7ec', 1, NULL, NULL);
INSERT INTO track VALUES ('modelos-datos', 'Modelos de Datos', 'Relacional, documento, grafo', 'Cómo se modela la información y qué compromete cada modelo.', 'datos-persistencia', 'planned', '#74c7ec', '#74c7ec', '#89b4fa', 0, NULL, NULL);
INSERT INTO track VALUES ('bases-datos', 'Bases de Datos', 'Motores e índices', 'Del árbol B al planificador de consultas: cómo un motor guarda y encuentra.', 'datos-persistencia', 'planned', '#74c7ec', '#74c7ec', '#89b4fa', 1, NULL, NULL);
INSERT INTO track VALUES ('transacciones', 'Transacciones', 'ACID y sus costes', 'Atomicidad, aislamiento y durabilidad: qué promete un motor y cómo lo paga.', 'datos-persistencia', 'planned', '#74c7ec', '#74c7ec', '#89b4fa', 2, NULL, NULL);
INSERT INTO track VALUES ('criptografia', 'Criptografía', 'Cifrar, firmar, verificar', 'Simétrica, asimétrica, hashes y firmas: las primitivas y sus usos correctos.', 'seguridad', 'planned', '#f38ba8', '#f38ba8', '#eba0ac', 0, NULL, NULL);
INSERT INTO track VALUES ('seguridad-sistemas', 'Seguridad de Sistemas', 'Ataques y defensas', 'Superficies de ataque, aislamiento, memoria segura y el modelo de amenazas.', 'seguridad', 'planned', '#f38ba8', '#f38ba8', '#eba0ac', 1, NULL, NULL);
